<template><div class="login-page"><el-card class="login-card"><h1>Flower Lottery</h1><p>管理后台</p><el-form :model="form" @submit.prevent="submit"><el-form-item><el-input v-model="form.username" placeholder="管理员账号"/></el-form-item><el-form-item><el-input v-model="form.password" type="password" show-password placeholder="密码"/></el-form-item><el-button type="primary" native-type="submit" :loading="loading" class="full">登录</el-button></el-form></el-card></div></template>
<script setup lang="ts">import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {http} from '@/api/http';import {useAuthStore} from '@/stores/auth';const form=reactive({username:'admin',password:''});const loading=ref(false);const router=useRouter();const auth=useAuthStore();async function submit(){loading.value=true;try{const result:any=await http.post('/auth/login',form);auth.setToken(result.data?.access_token ?? result.access_token);router.push('/dashboard')}catch{ElMessage.error('登录接口尚未完成或账号密码错误')}finally{loading.value=false}}</script>
